ALTER TABLE public.shifts ADD COLUMN clock_in_location jsonb,ADD COLUMN clock_out_location jsonb;
CREATE OR REPLACE FUNCTION public.record_shift_location(_shift uuid,_event text,_latitude double precision,_longitude double precision,_accuracy double precision) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.shifts; payload jsonb; BEGIN SELECT * INTO s FROM public.shifts WHERE id=_shift AND user_id=auth.uid() AND company_id=public.current_company_id() AND shift_type='shift' FOR UPDATE; IF NOT FOUND OR NOT public.member_is_active(auth.uid()) OR NOT public.company_module_access(s.company_id,'tracking') THEN RAISE EXCEPTION 'Own active company shift and tracking access required'; END IF; IF _event NOT IN('clock_in','clock_out') OR _latitude IS NULL OR _longitude IS NULL OR _accuracy IS NULL OR _latitude NOT BETWEEN -90 AND 90 OR _longitude NOT BETWEEN -180 AND 180 OR _accuracy NOT BETWEEN 0 AND 100000 THEN RAISE EXCEPTION 'Invalid location reading'; END IF; IF _event='clock_in' AND (s.clock_in_location IS NOT NULL OR s.ended_at IS NOT NULL OR s.started_at<now()-interval '2 minutes') THEN RAISE EXCEPTION 'Clock-in reading already captured or too late'; END IF; IF _event='clock_out' AND (s.clock_out_location IS NOT NULL OR s.ended_at IS NOT NULL) THEN RAISE EXCEPTION 'Clock-out reading must precede closing the shift'; END IF; payload:=jsonb_build_object('latitude',_latitude,'longitude',_longitude,'accuracy',_accuracy,'recorded_at',now()); IF _event='clock_in' THEN UPDATE public.shifts SET clock_in_location=payload WHERE id=s.id; ELSE UPDATE public.shifts SET clock_out_location=payload WHERE id=s.id; END IF; END $$;
REVOKE ALL ON FUNCTION public.record_shift_location(uuid,text,double precision,double precision,double precision) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_shift_location(uuid,text,double precision,double precision,double precision) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_shift_location_evidence() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN IF NEW.clock_in_location IS NOT NULL OR NEW.clock_out_location IS NOT NULL THEN RAISE EXCEPTION 'Use the location capture action'; END IF; ELSIF (NEW.clock_in_location IS DISTINCT FROM OLD.clock_in_location OR NEW.clock_out_location IS DISTINCT FROM OLD.clock_out_location) AND current_user IN('authenticated','anon','authenticator') THEN RAISE EXCEPTION 'Shift location evidence must use the guarded capture action'; END IF; RETURN NEW; END $$;
CREATE TRIGGER shifts_location_evidence BEFORE INSERT OR UPDATE ON public.shifts FOR EACH ROW EXECUTE FUNCTION public.guard_shift_location_evidence();
CREATE OR REPLACE FUNCTION public.shift_location_day(_user uuid,_date date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_company_manager() OR NOT public.member_is_active(auth.uid()) OR NOT public.company_module_access(public.current_company_id(),'tracking') THEN RAISE EXCEPTION 'Manager tracking access required'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'started_at',s.started_at,'ended_at',s.ended_at,'vehicle_reg',s.vehicle_reg,'clock_in_location',s.clock_in_location,'clock_out_location',s.clock_out_location) ORDER BY s.started_at),'[]'::jsonb) FROM public.shifts s WHERE s.company_id=public.current_company_id() AND s.user_id=_user AND s.shift_type='shift' AND s.started_at<((_date+1)::timestamp AT TIME ZONE 'Europe/Malta') AND coalesce(s.ended_at,now())>=(_date::timestamp AT TIME ZONE 'Europe/Malta')); END $$;
REVOKE ALL ON FUNCTION public.shift_location_day(uuid,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.shift_location_day(uuid,date) TO authenticated;
CREATE OR REPLACE FUNCTION public.hq_apply_setup_now(_subscription uuid,_plan uuid,_packs uuid[],_seats integer,_cadence text,_price numeric,_modes jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.platform_subscriptions; module text; mode text; BEGIN IF NOT public.is_platform_owner() THEN RAISE EXCEPTION 'Platform owner access required'; END IF; SELECT * INTO s FROM public.platform_subscriptions WHERE id=_subscription FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Subscription unavailable'; END IF; IF _seats IS NULL OR _price IS NULL OR _seats<0 OR _price<0 OR _cadence IS NULL OR _cadence NOT IN('monthly','quarterly','yearly') OR _modes IS NULL OR jsonb_typeof(_modes)<>'object' THEN RAISE EXCEPTION 'Invalid package settings'; END IF; UPDATE public.platform_subscriptions SET plan_id=_plan,pack_ids=coalesce(_packs,'{}'),seats=_seats,cadence=_cadence,agreed_price=_price,pending_change=NULL,trial_package_only=(_plan IS NOT NULL) WHERE id=s.id; DELETE FROM public.platform_overrides WHERE subscription_id=s.id AND reason='Setup package'; FOR module,mode IN SELECT key,value FROM jsonb_each_text(_modes) LOOP IF mode NOT IN('on','off','package') OR NOT EXISTS(SELECT 1 FROM public.platform_products WHERE id=s.product_id AND module=ANY(modules)) THEN RAISE EXCEPTION 'Invalid module mode'; END IF; IF module<>'core' AND mode<>'package' THEN INSERT INTO public.platform_overrides(subscription_id,module,enabled,starts_at,ends_at,reason) VALUES(s.id,module,mode='on',now(),'2099-12-31T23:59:59Z','Setup package'); END IF; END LOOP; END $$;